DO $$
DECLARE p public.qard_movimientos; req uuid; req2 uuid; adm uuid; n integer:=0; failed boolean; claims text; b numeric; remaining numeric; outp jsonb;
BEGIN
 claims:=current_setting('request.jwt.claims',true);
 SELECT user_id INTO adm FROM public.user_roles WHERE role='admin' ORDER BY user_id LIMIT 1;
 BEGIN
 FOR p IN SELECT m.* FROM public.qard_movimientos m JOIN public.qard_sub_qr s ON s.id=m.sub_qr_id WHERE m.tipo='cobro_comercio' AND (m.metadata->>'terminal'='collection' OR m.metadata->>'flujo'='payer_qr') AND s.sub_index IN(0,2) AND public.qard_refund_remaining(m.id)>=0.03 AND NOT EXISTS(SELECT 1 FROM public.qard_refund_requests WHERE payer_movement_id=m.id) ORDER BY s.sub_index LOOP
  n:=n+1;
  SELECT saldo_comercio_mxn INTO b FROM public.qard_wallets WHERE titular_user_id=p.comercio_user_id;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',p.titular_user_id,'role','authenticated')::text,true);
  req:=public.qard_refund_submit(p.id,0.03,'Producto devuelto',gen_random_uuid());
  IF (SELECT expires_at-created_at FROM public.qard_refund_requests WHERE id=req)<>interval '72 hours' THEN RAISE EXCEPTION '72-hour rule failed'; END IF;
  PERFORM public.qard_refund_action(req,'cancel');
  IF (SELECT status FROM public.qard_refund_requests WHERE id=req)<>'cancelled' THEN RAISE EXCEPTION 'Cancellation failed'; END IF;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',p.comercio_user_id,'role','authenticated')::text,true);
  failed:=false; BEGIN PERFORM public.qard_refund_decide(req,true,0.03); EXCEPTION WHEN OTHERS THEN failed:=true; END;
  IF NOT failed THEN RAISE EXCEPTION 'Cancelled request settled'; END IF;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',p.titular_user_id,'role','authenticated')::text,true);
  req:=public.qard_refund_submit(p.id,0.03,'Cobro duplicado',gen_random_uuid());
  UPDATE public.qard_refund_requests SET expires_at=now()-interval '1 second' WHERE id=req;
  PERFORM qard_private.qard_refund_expire();
  IF (SELECT status FROM public.qard_refund_requests WHERE id=req)<>'timed_out' THEN RAISE EXCEPTION 'Timeout failed'; END IF;
  PERFORM public.qard_refund_action(req,'dispute','No estoy de acuerdo');
  IF (SELECT status FROM public.qard_refund_requests WHERE id=req)<>'disputed' THEN RAISE EXCEPTION 'Dispute failed'; END IF;
  failed:=false; BEGIN PERFORM public.qard_refund_submit(p.id,0.01,'Otro motivo',gen_random_uuid()); EXCEPTION WHEN OTHERS THEN failed:=true; END;
  IF NOT failed THEN RAISE EXCEPTION 'Disputed original reused'; END IF;
  failed:=false; BEGIN UPDATE public.qard_wallets SET saldo_comercio_mxn=0.02 WHERE titular_user_id=p.comercio_user_id; EXCEPTION WHEN OTHERS THEN failed:=true; END;
  IF NOT failed THEN RAISE EXCEPTION 'Frozen balance spent'; END IF;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub','11111111-1111-1111-1111-111111111111','role','authenticated')::text,true);
  failed:=false; BEGIN PERFORM public.qard_refund_action(req,'resolve','No corresponde',false); EXCEPTION WHEN OTHERS THEN failed:=true; END;
  IF NOT failed THEN RAISE EXCEPTION 'Client resolved dispute'; END IF;
  IF adm IS NULL THEN RAISE EXCEPTION 'No admin fixture available'; END IF;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',adm,'role','authenticated')::text,true);
  PERFORM public.qard_refund_action(req,'resolve','Devolución comprobada',true,0.01);
  PERFORM public.qard_refund_action(req,'resolve','Devolución comprobada',true,0.01);
  IF (SELECT count(*) FROM public.qard_movimientos WHERE metadata->>'refund_request_id'=req::text)<>2 THEN RAISE EXCEPTION 'Admin retry duplicated money'; END IF;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',p.titular_user_id,'role','authenticated')::text,true);
  req2:=public.qard_refund_submit(p.id,0.01,'Producto devuelto',gen_random_uuid());
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub','11111111-1111-1111-1111-111111111111','role','authenticated')::text,true);
  failed:=false; BEGIN PERFORM public.qard_refund_decide(req2,true,0.01); EXCEPTION WHEN OTHERS THEN failed:=true; END;
  IF NOT failed THEN RAISE EXCEPTION 'Nonowner settled'; END IF;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',p.comercio_user_id,'role','authenticated')::text,true);
  failed:=false; BEGIN UPDATE public.qard_wallets SET saldo_comercio_mxn=0 WHERE titular_user_id=p.comercio_user_id; PERFORM public.qard_refund_decide(req2,true,0.01); EXCEPTION WHEN OTHERS THEN failed:=true; END;
  IF NOT failed THEN RAISE EXCEPTION 'Insufficient balance settled'; END IF;
  PERFORM public.qard_refund_decide(req2,true,0.01);
  IF (SELECT metadata->>'partial_index' FROM public.qard_movimientos WHERE id=(SELECT payer_refund_id FROM public.qard_refund_requests WHERE id=req2))<>'2' THEN RAISE EXCEPTION 'Partial number failed'; END IF;
  IF (SELECT saldo_comercio_mxn FROM public.qard_wallets WHERE titular_user_id=p.comercio_user_id)<>b-0.02 THEN RAISE EXCEPTION 'Business reconciliation failed'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.qard_movimientos WHERE id=p.id AND monto_mxn=p.monto_mxn AND metadata=p.metadata) THEN RAISE EXCEPTION 'Original changed'; END IF;
  IF (SELECT count(*) FROM public.qard_refund_notifications WHERE request_id=req)=0 THEN RAISE EXCEPTION 'Notification missing'; END IF;
  remaining:=public.qard_refund_remaining(p.id);
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',p.titular_user_id,'role','authenticated')::text,true);
  failed:=false; BEGIN PERFORM public.qard_refund_submit(p.id,remaining+0.01,'Producto devuelto',gen_random_uuid()); EXCEPTION WHEN OTHERS THEN failed:=true; END;
  IF NOT failed THEN RAISE EXCEPTION 'Total cap bypassed'; END IF;
 END LOOP;
 IF n=0 THEN RAISE EXCEPTION 'No real payment fixtures checked'; END IF;
 RAISE NOTICE 'Checked % real payment fixtures; all changes rolled back',n;
 RAISE EXCEPTION USING ERRCODE='Z0001',MESSAGE='checks passed; rollback fixtures';
 EXCEPTION WHEN SQLSTATE 'Z0001' THEN NULL;
 END;
 PERFORM set_config('request.jwt.claims',coalesce(claims,''),true);
END $$;